def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    prev_bids = []
    desperate_count = 0
    rich_live = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 1.2:
            rich_live += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if day >= 8:
        urgency += 1

    pressure = scarcity + urgency
    if desperate_count >= 2:
        pressure += 1

    if pressure >= 6:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif pressure >= 4:
        target = max(DAILY_SALARY * 0.78, avg_prev + 1.5)
    elif pressure >= 2:
        target = max(DAILY_SALARY * 0.52, min(highest_prev * 0.72, DAILY_SALARY * 0.72))
    else:
        target = DAILY_SALARY * 0.28

    if scarcity == 0 and hp >= 7 and no_water == 0:
        target = min(target, DAILY_SALARY * 0.35)

    if rich_live == 0 and pressure <= 2:
        target = min(target, DAILY_SALARY * 0.3)

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 0.35
    max_affordable = max(0.0, budget - reserve)
    if pressure >= 4:
        max_affordable = budget

    bid = min(target, max_affordable)
    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.9))

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and use yesterday's immediate bids
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure detection: if someone was bidding very aggressively, we match partially.
    aggressive_threshold = DAILY_SALARY * 0.85  # 76.5

    # Supply-based aggressiveness: more supply means less need to overbid.
    # target_water_units: how many units we aim to secure (0..2 typically)
    target_water_units = 1
    if supply >= 21.0:
        target_water_units = 2
    else:
        target_water_units = 1

    # Convert desired water units into a bid heuristic using water requirement.
    # Since the game mechanics aren't provided, we use a monotone mapping:
    # more desired units => higher bid, scaled by remaining days and hp.
    remaining_days = max(1, int(10 - day))
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])

    # Safety factor: if low hp, bid harder.
    if hp <= 1:
        hp_factor = 0.95
    elif hp == 2:
        hp_factor = 0.85
    elif hp == 3:
        hp_factor = 0.75
    else:
        hp_factor = 0.65

    # If aggressive bids were seen, we slightly increase to avoid losing.
    if highest_prev_bid >= aggressive_threshold:
        base = DAILY_SALARY * (0.35 if hp > 3 else 0.75)
    else:
        base = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

    # Supply adjustment: when supply is high, we can bid less; when low, bid more.
    supply_factor = 1.0
    if supply <= 17.0:
        supply_factor = 1.08
    elif supply >= 23.0:
        supply_factor = 0.92

    # Desired units adjustment
    units_factor = 1.0 if target_water_units <= 1 else 1.25

    # Time pressure: later days should preserve budget but ensure survival; bid a bit more earlier.
    time_factor = 1.0
    if remaining_days <= 3:
        time_factor = 1.08
    elif remaining_days >= 7:
        time_factor = 0.95

    bid = base * hp_factor * supply_factor * units_factor * time_factor

    # Budget cap: never exceed budget.
    bid = max(0.0, min(budget, bid))

    # Additional cap to avoid overextending in medium scenario.
    # Keep bids under ~0.9*DAILY_SALARY unless hp is critical.
    if hp > 2:
        bid = min(bid, DAILY_SALARY * 0.85)
    else:
        bid = min(bid, DAILY_SALARY * 0.98)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
